Builds a CfbStorage/CfbStream tree directly (a nested storage holding one stream, plus a top-level stream), wraps it in a CfbDocument, serialises it with CfbWriter.ToBytes and reads the resulting bytes back with the CfbReader(byte[]) constructor, walking CfbReader.IterTree to confirm every hand-built storage and stream round-trips.

Example:
// Authored example: build a CFB container by hand and read it back with CfbReader
using Aspose.Email.Foss.Cfb;

var root = new CfbStorage("Root Entry");
var folder = new CfbStorage("Folder");
folder.AddStream(new CfbStream("notes.txt", System.Text.Encoding.UTF8.GetBytes("hand-built CFB entry")));
root.AddStorage(folder);
root.AddStream(new CfbStream("manifest.txt", System.Text.Encoding.UTF8.GetBytes("v1")));

var document = new CfbDocument(root);
byte[] bytes = CfbWriter.ToBytes(document);

using var reader = new CfbReader(bytes);
var names = new List<string>();
foreach (var (depth, entry) in reader.IterTree())
{
    names.Add(new string(' ', depth * 2) + entry.Name);
}

Console.WriteLine("cfb bytes: " + bytes.Length);
Console.WriteLine("directory entries: " + reader.DirectoryEntryCount);
Console.WriteLine(string.Join(Environment.NewLine, names));

if (bytes.Length == 0)
{
    throw new Exception("expected non-empty CFB bytes");
}
if (!names.Any(name => name.Contains("Folder")))
{
    throw new Exception("expected the Folder storage to round-trip");
}
if (!names.Any(name => name.Contains("notes.txt")))
{
    throw new Exception("expected the nested notes.txt stream to round-trip");
}
if (!names.Any(name => name.Contains("manifest.txt")))
{
    throw new Exception("expected the top-level manifest.txt stream to round-trip");
}
