Sets a custom MAPI property with MapiMessage.SetProperty using a CommonMessagePropertyId/PropertyTypeCode pair that has no dedicated strongly-typed property, round-trips the message through an in-memory MemoryStream and reads the value back with GetPropertyValue, checking both the set value, that an unset tag comes back null, and that IterPropertyKeys reports at least one key.

Example:
// Authored example: set and read an arbitrary MAPI property beyond the strongly-typed ones
using Aspose.Email.Foss.Msg;

var message = MapiMessage.Create("Build status", "Build 4821 finished.");
message.SetProperty(
    (ushort)CommonMessagePropertyId.ExampleTag100A,
    (ushort)PropertyTypeCode.PtypString,
    "ci-pipeline-4821");

using var stream = new MemoryStream();
message.Save(stream);
stream.Position = 0;
using var loaded = MapiMessage.FromStream(stream);

var value = loaded.GetPropertyValue(
    (ushort)CommonMessagePropertyId.ExampleTag100A,
    (ushort)PropertyTypeCode.PtypString);
var missing = loaded.GetPropertyValue(
    (ushort)CommonMessagePropertyId.ExampleTag101D,
    (ushort)PropertyTypeCode.PtypString);
var keyCount = loaded.IterPropertyKeys().Count();

Console.WriteLine("custom property value: " + value);
Console.WriteLine("missing property value: " + (missing ?? "<null>"));
Console.WriteLine("property key count: " + keyCount);

if ((value as string) != "ci-pipeline-4821")
{
    throw new Exception("custom property value mismatch");
}
if (missing is not null)
{
    throw new Exception("expected the unset tag to come back null");
}
if (keyCount == 0)
{
    throw new Exception("expected at least one property key");
}
